perl -e '
use strict; use warnings;
my $root = "/bench/repo";
my $internal = "$root/internal";

my @syms;
for my $path (glob("$internal/*"), glob("$internal/*/*"), glob("$internal/*/*/*"), glob("$internal/*/*/*/*")) {
  next unless -f $path && $path =~ /\.go$/ && $path !~ /_test\.go$/;
  open my $fh, "<", $path or next;
  my $pkg = "";
  my $rel = $path; $rel =~ s/^\Q$root\E\///;
  while (<$fh>) {
    $pkg = $1 if /^package\s+(\w+)/;
  }
  seek $fh, 0, 0;
  while (<$fh>) {
    if (/^func\s+\(([^)]+)\)\s+([A-Z]\w*)\s*\(/) {
      my ($recv, $name) = ($1, $2);
      $recv =~ s/^\*?(\w+).*/$1/;
      push @syms, { pkg=>$pkg, recv=>$recv, name=>$name, rel=>$rel, qual=>"${pkg}.${recv}.${name}" };
    } elsif (/^func\s+([A-Z]\w*)\s*\(/) {
      push @syms, { pkg=>$pkg, recv=>"", name=>$1, rel=>$rel, qual=>"$pkg.$1" };
    }
  }
  close $fh;
}

sub count_refs {
  my ($sym) = @_;
  my ($pkg, $recv, $name, $qual) = @$sym{qw/pkg recv name qual/};
  my @files = glob("$root/{cmd,internal,server,store}/**/*.go");
  my $count = 0;
  for my $f (@files) {
    next if $f =~ /\/proto\/gen\//;
    open my $fh, "<", $f or next;
    while (<$fh>) {
      next if /^\s*func\s+/; # skip declarations
      if (!$recv) {
        $count++ if /\Q$qual(/ || /\Q$qual\b/;
      } else {
        # method call .Name(
        $count++ if /\.$name\s*\(/;
      }
    }
    close $fh;
  }
  return $count;
}

my @results;
for my $s (@syms) {
  my $c = count_refs($s);
  my $sym = $s->{recv} ? "$s->{recv}.$s->{name}" : $s->{name};
  push @results, [$c, $sym, $s->{rel}, $s->{qual}];
}
@results = sort { $b->[0] <=> $a->[0] } @results;
print "Top 25:\n";
for my $i (0..24) {
  printf "%4d  %-35s %s\n", $results[$i][0], $results[$i][1], $results[$i][2];
}
'

